// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;
    function setUp() public { c = new PrivateBank(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor, address origin) public {
        vm.assume(actor != origin);
        vm.assume(actor != address(c));
        vm.assume(origin != address(c));
        vm.deal(actor, type(uint256).max / 2);
        amount = bound(amount, c.MinDeposit(), type(uint256).max / 4);

        uint256 before = c.balances(actor);
        vm.startPrank(actor, origin);
        c.Deposit{value: amount}();
        vm.stopPrank();

        assertTrue(c.balances(actor) == before + amount, "Deposit must credit msg.sender");
    }
}
